import re
HOST = re.compile(r"[A-Za-z0-9.-]{1,253}")

def safe_host(h):
    return bool(HOST.fullmatch(h)) and not h.startswith("-")

for h in ["example.com", "example.com; echo x", "-oProxyCommand=x"]:
    print(h, safe_host(h))

from jinja2 import Environment
env = Environment(autoescape=True)

def greet(name):
    # VULNERABLE: the user's text becomes part of the template source
    return env.from_string("Hello " + name + "!").render()

def greet_fixed(name):
    # FIXED: the template is a constant; name is passed in as data
    return env.from_string("Hello {{ name }}!").render(name=name)

greet("Ana")              # Hello Ana!
greet("{{ 7*7 }}")        # Hello 49!          the server did arithmetic
greet_fixed("{{ 7*7 }}")  # Hello {{ 7*7 }}!   printed as text

